package dev.pocketengine.phone.observation;

import android.app.Application;
import android.database.sqlite.SQLiteDatabase;
import dev.pocketengine.core.*;
import dev.pocketengine.features.capabilities.ModelCapabilityAdapters;
import dev.pocketengine.runtime.AgentRunner;
import dev.pocketengine.store.TaskStore;
import dev.pocketengine.testutil.HttpServer;
import java.lang.reflect.Field;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.json.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.annotation.Config;
import org.robolectric.annotation.SQLiteMode;
import static org.junit.Assert.*;
import static dev.pocketengine.phone.observation.PhoneCollectionFixtures.j;

/** Original Runner/TaskStore and native plan producer; physical accessibility/model are explicit fixtures. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class PhoneTreeSequenceJournalTest {
    static final class F implements AutoCloseable {
        final TaskStore tasks=new TaskStore(RuntimeEnvironment.getApplication());final RunControl control=new RunControl();final List<JSONObject> events=new CopyOnWriteArrayList<>();final AtomicLong clock=new AtomicLong(1000);final AtomicInteger effects=new AtomicInteger(),reads=new AtomicInteger();final AtomicReference<String> last=new AtomicReference<>();final List<Boolean> images=new ArrayList<>();final String task,run;final int epoch;final ModelCapabilityAdapters.Binding binding;final AdaptivePhonePort phone;final CapabilityPort cap;final RunJournal journal;volatile boolean changeNext,unknown,cancelAfterFirst;
        F()throws Exception {
            JSONObject row=tasks.startAttempt(tasks.create("执行明确的两个手机步骤，可随时停止","main_screen").getString("id"),"main_screen",30);task=row.getString("id");run=row.getString("runId");epoch=row.getInt("coordinatorEpoch");control.bindHostRun(task,run,epoch);binding=new ModelCapabilityAdapters.Binding(task,run,epoch,control,true,"");
            PhonePort actual=new PhonePort(){public boolean isConnected(){return true;}public void clearReferences(){}public JSONObject observe(boolean image,RunControl original)throws Exception{assertSame(control,original);images.add(image);reads.incrementAndGet();String actualId=UUID.randomUUID().toString();last.set(actualId);JSONObject o=PhoneTreeSequenceTest.actual(actualId).put("observedAtUptimeMs",clock.get());if(effects.get()>0){o.getJSONArray("nodes").getJSONObject(2).put("identityFingerprint","150:"+"f".repeat(64));if(changeNext)o.getJSONArray("nodes").getJSONObject(4).put("identityFingerprint","151:"+"a".repeat(64));}return o;}
                public JSONObject execute(String tool,JSONObject args,RunControl original)throws Exception{assertSame(control,original);assertTrue(tool.matches("phone_click_node|phone_type"));JSONArray ops=tasks.get(task,false).getJSONArray("operations");assertEquals(effects.get()+1,ops.length());JSONObject prepared=ops.getJSONObject(ops.length()-1);assertEquals("prepared",prepared.getString("state"));assertEquals(tool,prepared.getString("tool"));assertEquals(TaskStore.capabilityFingerprint(args),TaskStore.capabilityFingerprint(prepared.getJSONObject("arguments")));int count=effects.incrementAndGet();if(cancelAfterFirst&&count==1)control.cancel();return j("ok",!unknown,"accepted",unknown?JSONObject.NULL:true,"verified",false,"error",unknown?"action_unknown":"");}
            };
            phone=new AdaptivePhonePort(actual,new AdaptivePhonePort.Scope(task,run,epoch,"s",5),false,false,clock::get);
            CapabilityPort base=new CapabilityPort(){public JSONArray tools(){return new JSONArray();}public boolean supports(String n){return false;}public boolean sideEffecting(String n){return false;}public JSONObject execute(String n,JSONObject a,RunControl c){throw new AssertionError("no plan executor in capability port");}};
            cap=PhoneTreeCapabilityPort.bindIfAvailable(base,tasks,binding,control,phone);JSONArray names=new JSONArray().put("phone_click_node").put("phone_type"),definitions=cap.tools();for(int i=0;i<definitions.length();i++)names.put(definitions.getJSONObject(i).getJSONObject("function").getString("name"));tasks.authorizeTools(task,run,names);tasks.status(task,"running","native sequence fixture admitted");journal=tasks.journal(task,run,epoch,control);
        }
        public void close()throws Exception{cap.close();control.cancel();Field f=TaskStore.class.getDeclaredField("db");f.setAccessible(true);((SQLiteDatabase)f.get(tasks)).close();}
    }
    static RunOutcome run(F x,AtomicInteger requests)throws Exception {return run(x,requests,null,0);}
    static RunOutcome run(F x,AtomicInteger requests,String waitText,int timeoutMs)throws Exception {
        AtomicReference<Throwable> failed=new AtomicReference<>();HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);ExecutorService worker=Executors.newSingleThreadExecutor();
        server.createContext("/",exchange->{try{JSONObject request=new JSONObject(new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8)),answer;
            if(requests.getAndIncrement()==0){String observed=x.last.get();assertNotNull("real initial Runner observation",observed);assertTrue("actual model request contains initial native tree",request.getJSONArray("messages").toString().contains(observed));JSONObject proposal=(waitText==null?PhoneTreeSequenceTest.proposal(PhoneTreeSequenceTest.click(),PhoneTreeSequenceTest.type()):PhoneTreeSequenceTest.proposal(j("tool",PhoneTreeQuery.WAIT,"condition",j("kind","present","selector",j("text",waitText),"timeoutMs",timeoutMs)),PhoneTreeSequenceTest.click())).put("observationId",observed);answer=j("role","assistant","content",JSONObject.NULL,"tool_calls",new JSONArray().put(j("id","actual_read_parent_call","type","function","function",j("name",PhoneTreeSequence.TOOL,"arguments",proposal.toString()))));}
            else{assertEquals("No extra model round between deterministic child steps",2,requests.get());answer=j("role","assistant","content","已依据逐步真实回执结束；停止或变化时不重发剩余步骤，业务结果请主人核对。");}
            byte[] response=j("choices",new JSONArray().put(j("message",answer,"finish_reason",answer.has("tool_calls")?"tool_calls":"stop"))).toString().getBytes(StandardCharsets.UTF_8);exchange.sendResponseHeaders(200,response.length);exchange.getResponseBody().write(response);
        }catch(Throwable failure){failed.compareAndSet(null,failure);try{exchange.sendResponseHeaders(500,0);}catch(Exception ignored){}}finally{exchange.close();}});server.start();
        try{ModelConfig config=new ModelConfig("http://127.0.0.1:"+server.getAddress().getPort(),"local-fixture-only","native-short-sequence",false,30,10);RunOutcome outcome=worker.submit(()->new AgentRunner(x.phone,x.cap).run(x.task,"依次点击已展示按钮并填写另一明确输入，不做其他操作",config,x.control,event->{x.events.add(event);try{x.tasks.event(x.task,x.run,x.epoch,event);}catch(Exception failure){throw new IllegalStateException(failure);}},x.journal)).get(25,TimeUnit.SECONDS);if(failed.get()!=null)throw new AssertionError("explicit local model fixture",failed.get());return outcome;}finally{worker.shutdownNow();worker.awaitTermination(2,TimeUnit.SECONDS);server.stop(0);}
    }
    static void remaining(F x)throws Exception {JSONObject progress=null;for(JSONObject event:x.events)if(event.optString("type").equals("native_sequence")&&event.optString("status").equals("not_dispatched"))progress=event.getJSONObject("receipt");assertNotNull("original Runner explicitly reports un-dispatched remaining child",progress);assertEquals("actual_read_parent_call",progress.getString("parentOperationId"));assertEquals(2,progress.getInt("totalSteps"));assertEquals(1,progress.getInt("dispatchEnteredSteps"));assertEquals(1,progress.getInt("remainingSteps"));assertEquals(2,progress.getInt("firstNotDispatchedStep"));assertFalse(progress.getBoolean("automaticReplay"));assertFalse(progress.getBoolean("executionAuthorized"));}
    @Test public void twoFreshChildrenUseOriginalJournalPerStepAndOnlyOneProposalModelRound()throws Exception {try(F x=new F()){AtomicInteger calls=new AtomicInteger();RunOutcome outcome=run(x,calls);assertTrue(outcome.summary,outcome.status.matches("completed|needs_confirmation"));assertEquals(2,x.effects.get());assertEquals(2,calls.get());assertFalse(x.images.contains(true));JSONArray ops=x.tasks.get(x.task,false).getJSONArray("operations");assertEquals(2,ops.length());for(int i=0;i<ops.length();i++){assertEquals("receipt",ops.getJSONObject(i).getString("state"));assertEquals(x.run,ops.getJSONObject(i).getString("runId"));}assertEquals("phone_click_node",ops.getJSONObject(0).getString("tool"));assertEquals("phone_type",ops.getJSONObject(1).getString("tool"));String messages=x.journal.restore().getJSONArray("messages").toString();assertTrue(messages.contains("actual_read_parent_call"));assertTrue(messages.contains("native_"));assertTrue(messages.contains("literal user text"));}}
    @Test public void changedSecondTargetStopsWithoutRetargetOrPreparedSecondOperation()throws Exception {try(F x=new F()){x.changeNext=true;RunOutcome outcome=run(x,new AtomicInteger());assertEquals(1,x.effects.get());assertEquals(1,x.tasks.get(x.task,false).getJSONArray("operations").length());assertTrue(x.events.toString().contains("native_sequence_not_dispatched"));remaining(x);assertFalse(x.images.contains(true));}}
    @Test public void unknownFirstDispatchNeverReplaysOrPreparesTheSecondChild()throws Exception {try(F x=new F()){x.unknown=true;AtomicInteger requests=new AtomicInteger();RunOutcome outcome=run(x,requests);assertEquals("awaiting_user",outcome.status);assertEquals(1,x.effects.get());assertEquals(1,requests.get());assertEquals(1,x.tasks.get(x.task,false).getJSONArray("operations").length());assertEquals(JSONObject.NULL,x.tasks.get(x.task,false).getJSONArray("operations").getJSONObject(0).getJSONObject("receipt").get("accepted"));remaining(x);}}
    @Test public void ownerCancellationAfterFirstDispatchHasNoFurtherChildReadOrEffect()throws Exception {try(F x=new F()){x.cancelAfterFirst=true;AtomicInteger requests=new AtomicInteger();RunOutcome outcome=run(x,requests);assertEquals("cancelled",outcome.status);assertEquals(1,x.effects.get());assertEquals(1,requests.get());assertEquals(1,x.tasks.get(x.task,false).getJSONArray("operations").length());remaining(x);}}
    private static JSONObject conditionReceipt(F x)throws Exception {for(JSONObject event:x.events)if(event.optString("type").equals("tool")&&PhoneTreeQuery.WAIT.equals(event.optString("tool"))&&event.optJSONObject("receipt")!=null&&event.getJSONObject("receipt").has("matched"))return event.getJSONObject("receipt");throw new AssertionError("original condition-wait receipt not delivered");}
    @Test public void timedOutWaitDoesNotDispatchTheRemainingExistingClick()throws Exception {try(F x=new F()){AtomicInteger requests=new AtomicInteger();RunOutcome outcome=run(x,requests,"NEVER-APPEARS-IN-NATIVE-FIXTURE",100);JSONObject waited=conditionReceipt(x);assertTrue("ordinary read timeout is still a valid native observation",waited.getBoolean("ok"));assertEquals("timed_out",waited.getString("status"));assertFalse(waited.getBoolean("matched"));assertEquals("unmet native predicate must stop before clicking an otherwise existing button",0,x.effects.get());assertEquals(0,x.tasks.get(x.task,false).getJSONArray("operations").length());remaining(x);assertEquals(2,requests.get());assertFalse(x.control.isCancelled());assertFalse(x.images.contains(true));assertTrue(outcome.summary,outcome.status.matches("completed|needs_confirmation"));}}
    @Test public void matchedWaitStillDispatchesTheNextClickThroughItsOriginalPreparedJournal()throws Exception {try(F x=new F()){AtomicInteger requests=new AtomicInteger();RunOutcome outcome=run(x,requests,"Button",1000);JSONObject waited=conditionReceipt(x);assertTrue(waited.getBoolean("ok"));assertEquals("matched",waited.getString("status"));assertTrue(waited.getBoolean("matched"));assertEquals(1,x.effects.get());assertEquals(2,requests.get());JSONArray operations=x.tasks.get(x.task,false).getJSONArray("operations");assertEquals(1,operations.length());assertEquals("phone_click_node",operations.getJSONObject(0).getString("tool"));assertEquals("receipt",operations.getJSONObject(0).getString("state"));assertEquals(x.run,operations.getJSONObject(0).getString("runId"));assertFalse(x.events.toString().contains("\"status\":\"not_dispatched\""));assertFalse(x.control.isCancelled());assertTrue(outcome.summary,outcome.status.matches("completed|needs_confirmation"));}}
    @Test public void standaloneNativeConditionTimeoutRetainsItsOriginalReadOnlyMeaning()throws Exception {try(F x=new F()){JSONObject receipt=x.cap.execute(PhoneTreeQuery.WAIT,j("kind","present","selector",j("text","NEVER-APPEARS-IN-NATIVE-FIXTURE"),"timeoutMs",100),x.control);assertTrue(receipt.getBoolean("ok"));assertEquals("timed_out",receipt.getString("status"));assertFalse(receipt.getBoolean("matched"));assertFalse(receipt.getBoolean("sideEffecting"));assertEquals(0,x.effects.get());assertEquals(0,x.tasks.get(x.task,false).getJSONArray("operations").length());assertFalse(x.control.isCancelled());}}
}
